 "<b style=\"font-size:27px;color:#c43f3f\">Ergonomía</b><br><span style=\"font-size:22px;color:#30220e\">Posturas, cargas, repetición.</span>": "<b style=\"font-size:27px;color:#c43f3f\">Ergonomie</b><br><span style=\"font-size:22px;color:#30220e\">Haltungen, Lasten, Wiederholung.</span>",
